-- PublicEcho Large Seed File 4: 1,000 Complaints & assignments
USE publicecho;

ON DUPLICATE KEY UPDATE `user_id` = VALUES(`user_id`), `category_id` = VALUES(`category_id`), `status_id` = VALUES(`status_id`), `ward_id` = VALUES(`ward_id`), `title` = VALUES(`title`), `description` = VALUES(`description`), `latitude` = VALUES(`latitude`), `longitude` = VALUES(`longitude`), `address` = VALUES(`address`), `created_at` = VALUES(`created_at`), `updated_at` = VALUES(`updated_at`);

-- Assignments (for Assigned/In_Progress/Resolved complaints)
ON DUPLICATE KEY UPDATE `complaint_id` = VALUES(`complaint_id`), `official_id` = VALUES(`official_id`), `assigned_at` = VALUES(`assigned_at`), `resolved_at` = VALUES(`resolved_at`);
